def scarica_tutto(client, pagina_size=100):
    risultati = []
    pagina = 0
    while True:
        blocco = client.get(offset=pagina * pagina_size, limit=pagina_size)
        risultati.extend(blocco)
        if len(blocco) < pagina_size:
            break
        pagina += 1
    return risultati

